def binary_tree_diameter(root: TreeNode | None) -> int:
    if root is None:
        return 0
    if not isinstance(root, TreeNode):
        raise TypeError('root must be TreeNode or None')

    max_diameter = 0

    def _height(node: TreeNode | None) -> int:
        nonlocal max_diameter
        if node is None:
            return 0
        left_h = _height(node.left)
        right_h = _height(node.right)
        max_diameter = max(max_diameter, left_h + right_h)
        return 1 + max(left_h, right_h)

    _height(root)
    return max_diameter

import heapq

def merge_k_sorted_streams(*iterables):
    heap = []
    # Verificación de iterabilidad y obtención de iteradores
    active_iters = []
    for i, it in enumerate(iterables):
        try:
            iterator = iter(it)
            active_iters.append(iterator)
        except TypeError:
            raise TypeError('Arguments must be iterable')

    for i, iterator in enumerate(active_iters):
        try:
            val = next(iterator)
            # Almacenar (val, index_unico, iterator) para desempate seguro
            heapq.heappush(heap, (val, i, iterator))
        except StopIteration:
            pass

    idx_counter = len(active_iters)
    while heap:
        val, _, it = heapq.heappop(heap)
        yield val
        try:
            next_val = next(it)
            idx_counter += 1
            heapq.heappush(heap, (next_val, idx_counter, it))
        except StopIteration:
            pass

from collections import deque

def max_sliding_window(nums: list[int | float], k: int) -> list[int | float]:
    if not isinstance(nums, list):
        raise TypeError('nums must be a list of numbers')
    if not isinstance(k, int) or k <= 0:
        raise ValueError('k must be a positive integer')
    if not nums:
        return []
    for x in nums:
        if not isinstance(x, (int, float)) or isinstance(x, bool):
            raise TypeError('nums must be a list of numbers')
    if k > len(nums):
        raise ValueError('k cannot be greater than the length of nums')

    dq = deque()  # Almacenará índices de nums en orden monótono decreciente de valor
    res = []

    for i, x in enumerate(nums):
        # 1. Remover índices fuera de la ventana actual [i - k + 1, i]
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # 2. Mantener orden decreciente eliminando elementos menores o iguales
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        # 3. El frente del deque es el máximo de la ventana
        if i >= k - 1:
            res.append(nums[dq[0]])

    return res

import json

def canonical_json_dumps(obj) -> str:
    seen_ids = set()

    def _serialize(item):
        if item is None:
            return 'null'
        if isinstance(item, bool):
            return 'true' if item else 'false'
        if isinstance(item, int):
            return str(item)
        if isinstance(item, float):
            if item != item or item == float('inf') or item == float('-inf'):
                raise ValueError('NaN and Infinity not permitted in canonical JSON')
            # Representación compacta canónica estándar
            rep = repr(item)
            return rep
        if isinstance(item, str):
            return json.dumps(item, ensure_ascii=False)
        if isinstance(item, list):
            obj_id = id(item)
            if obj_id in seen_ids:
                raise ValueError('Circular reference detected')
            seen_ids.add(obj_id)
            parts = [_serialize(elem) for elem in item]
            seen_ids.remove(obj_id)
            return '[' + ','.join(parts) + ']'
        if isinstance(item, dict):
            obj_id = id(item)
            if obj_id in seen_ids:
                raise ValueError('Circular reference detected')
            seen_ids.add(obj_id)
            # Ordenamiento estricto lexicográfico de claves
            sorted_keys = sorted(item.keys())
            for k in sorted_keys:
                if not isinstance(k, str):
                    raise TypeError('Dictionary keys must be strings')
            parts = [json.dumps(k, ensure_ascii=False) + ':' + _serialize(item[k]) for k in sorted_keys]
            seen_ids.remove(obj_id)
            return '{' + ','.join(parts) + '}'
        raise TypeError('Unsupported type for canonical JSON')

    return _serialize(obj)

