import hashlib

class BloomFilter:
    def __init__(self, size: int, hash_count: int):
        if not isinstance(size, int) or not isinstance(hash_count, int) or size <= 0 or hash_count <= 0:
            raise ValueError('size and hash_count must be positive integers')
        self.size = size
        self.hash_count = hash_count
        self.bits = 0  # Bit array como entero grande

    def _get_hashes(self, item: str):
        # Doble hash criptográfico con salteado de índice
        raw = item.encode('utf-8')
        indices = []
        for i in range(self.hash_count):
            h = int(hashlib.sha256(raw + i.to_bytes(4, 'big')).hexdigest(), 16)
            indices.append(h % self.size)
        return indices

    def add(self, item: str) -> None:
        if not isinstance(item, str):
            raise TypeError('item must be a string')
        for idx in self._get_hashes(item):
            self.bits |= (1 << idx)

    def __contains__(self, item: str) -> bool:
        if not isinstance(item, str):
            raise TypeError('item must be a string')
        for idx in self._get_hashes(item):
            if not (self.bits & (1 << idx)):
                return False
        return True

