def flatten_binary_tree(root: TreeNode | None) -> None:
    if root is None:
        return
    if not isinstance(root, TreeNode):
        raise TypeError('root must be TreeNode or None')

    # Algoritmo de recorrido inverso post-orden con puntero previo (Right -> Left -> Root)
    prev = None
    def _reverse_postorder(curr):
        nonlocal prev
        if not curr:
            return
        _reverse_postorder(curr.right)
        _reverse_postorder(curr.left)
        curr.right = prev
        curr.left = None
        prev = curr

    _reverse_postorder(root)

from collections import defaultdict, deque

def dag_longest_path(num_nodes: int, edges: list[tuple[int, int, int]]) -> int:
    if not isinstance(num_nodes, int) or num_nodes <= 0:
        raise ValueError('num_nodes must be a positive integer')
    if not isinstance(edges, list):
        raise TypeError('edges must be a list of tuples')

    adj = defaultdict(list)
    in_degree = [0] * num_nodes

    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 3:
            raise TypeError('Each edge must be (u, v, weight)')
        u, v, w = e
        if not isinstance(u, int) or not isinstance(v, int) or not isinstance(w, (int, float)):
            raise TypeError('Edge components must be numeric')
        if u < 0 or u >= num_nodes or v < 0 or v >= num_nodes:
            raise IndexError('Edge node index out of bounds')
        adj[u].append((v, w))
        in_degree[v] += 1

    # Algoritmo de Kahn para orden topológico y detección de ciclos
    queue = deque([i for i in range(num_nodes) if in_degree[i] == 0])
    topo_order = []
    while queue:
        node = queue.popleft()
        topo_order.append(node)
        for neighbor, _ in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topo_order) != num_nodes:
        raise ValueError('Graph contains a cycle')

    # Programación dinámica sobre el orden topológico
    dist = [0] * num_nodes
    for u in topo_order:
        for v, weight in adj[u]:
            if dist[u] + weight > dist[v]:
                dist[v] = dist[u] + weight

    return max(dist) if dist else 0

