import time

def execute_with_retry(operation: callable, max_attempts: int = 3, base_delay: float = 0.01, max_delay: float = 0.1, retryable_exceptions: tuple = (Exception,)):
    if not callable(operation):
        raise TypeError('operation must be callable')
    if not isinstance(max_attempts, int) or max_attempts <= 0:
        raise ValueError('max_attempts must be >= 1')

    for attempt in range(max_attempts):
        try:
            return operation()
        except retryable_exceptions as e:
            if attempt == max_attempts - 1:
                raise e
            delay = min(base_delay * (2 ** attempt), max_delay)
            time.sleep(delay)

import threading

class BankAccount:
    def __init__(self, account_id: int, balance: float):
        self.account_id = account_id
        self.balance = float(balance)
        self.lock = threading.Lock()

def safe_account_transfer(from_acc: BankAccount, to_acc: BankAccount, amount: float) -> bool:
    if not isinstance(from_acc, BankAccount) or not isinstance(to_acc, BankAccount):
        raise TypeError('Accounts must be BankAccount instances')
    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        raise TypeError('amount must be numeric')
    if amount <= 0:
        raise ValueError('Transfer amount must be positive')
    if from_acc.account_id == to_acc.account_id:
        raise ValueError('Cannot transfer to the same account')

    # Orden canónico estricto de adquisición de locks para prevenir deadlock
    first_lock, second_lock = (
        (from_acc.lock, to_acc.lock) if from_acc.account_id < to_acc.account_id else (to_acc.lock, from_acc.lock)
    )

    with first_lock:
        with second_lock:
            if from_acc.balance < amount:
                return False
            from_acc.balance -= amount
            to_acc.balance += amount
            return True

class FenwickTree:
    def __init__(self, size: int):
        if not isinstance(size, int) or size <= 0:
            raise ValueError('size must be a positive integer')
        self.size = size
        self.tree = [0] * (size + 1)

    def update(self, idx: int, delta: int | float) -> None:
        if not isinstance(idx, int) or idx < 1 or idx > self.size:
            raise IndexError('Index out of bounds')
        if not isinstance(delta, (int, float)) or isinstance(delta, bool):
            raise TypeError('delta must be numeric')
        while idx <= self.size:
            self.tree[idx] += delta
            idx += idx & (-idx)

    def query(self, idx: int) -> int | float:
        if not isinstance(idx, int) or idx < 0 or idx > self.size:
            raise IndexError('Index out of bounds')
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & (-idx)
        return res

    def range_query(self, left: int, right: int) -> int | float:
        if not isinstance(left, int) or not isinstance(right, int):
            raise TypeError('Range indices must be integers')
        if left < 1 or right > self.size:
            raise IndexError('Range out of bounds')
        if left > right:
            raise ValueError('left index cannot be greater than right')
        return self.query(right) - self.query(left - 1)

class _Node:
    def __init__(self, val=None, prev=None, next_node=None):
        self.val = val
        self.prev = prev
        self.next = next_node

class DoublyLinkedDeque:
    def __init__(self):
        self._head = _Node()
        self._tail = _Node()
        self._head.next = self._tail
        self._tail.prev = self._head
        self._size = 0

    def __len__(self) -> int:
        return self._size

    def append(self, val) -> None:
        new_node = _Node(val, prev=self._tail.prev, next_node=self._tail)
        self._tail.prev.next = new_node
        self._tail.prev = new_node
        self._size += 1

    def appendleft(self, val) -> None:
        new_node = _Node(val, prev=self._head, next_node=self._head.next)
        self._head.next.prev = new_node
        self._head.next = new_node
        self._size += 1

    def pop(self):
        if self._size == 0:
            raise IndexError('pop from empty deque')
        target = self._tail.prev
        val = target.val
        target.prev.next = self._tail
        self._tail.prev = target.prev
        self._size -= 1
        return val

    def popleft(self):
        if self._size == 0:
            raise IndexError('popleft from empty deque')
        target = self._head.next
        val = target.val
        self._head.next = target.next
        target.next.prev = self._head
        self._size -= 1
        return val

    def peek(self):
        if self._size == 0:
            raise IndexError('peek from empty deque')
        return self._tail.prev.val

    def peekleft(self):
        if self._size == 0:
            raise IndexError('peekleft from empty deque')
        return self._head.next.val

class _RadixNode:
    def __init__(self, prefix: str = '', is_leaf: bool = False):
        self.prefix = prefix
        self.is_leaf = is_leaf
        self.children = {}  # first_char -> _RadixNode

class RadixTree:
    def __init__(self):
        self.root = _RadixNode()

    def insert(self, word: str) -> None:
        if not isinstance(word, str) or len(word) == 0:
            raise ValueError('word must be a non-empty string')

        curr = self.root
        i = 0
        while i < len(word):
            char = word[i]
            if char not in curr.children:
                curr.children[char] = _RadixNode(word[i:], is_leaf=True)
                return

            child = curr.children[char]
            edge = child.prefix
            # Encontrar prefijo común entre edge y word[i:]
            common_len = 0
            while common_len < len(edge) and i + common_len < len(word) and edge[common_len] == word[i + common_len]:
                common_len += 1

            if common_len == len(edge):
                i += common_len
                curr = child
            else:
                # Dividir la arista existente
                split_node = _RadixNode(edge[:common_len], is_leaf=False)
                child.prefix = edge[common_len:]
                split_node.children[child.prefix[0]] = child
                curr.children[char] = split_node

                i += common_len
                if i == len(word):
                    split_node.is_leaf = True
                else:
                    split_node.children[word[i]] = _RadixNode(word[i:], is_leaf=True)
                return

        curr.is_leaf = True

    def search(self, word: str) -> bool:
        if not isinstance(word, str) or not word:
            return False
        curr = self.root
        i = 0
        while i < len(word):
            char = word[i]
            if char not in curr.children:
                return False
            child = curr.children[char]
            edge = child.prefix
            if not word.startswith(edge, i):
                return False
            i += len(edge)
            curr = child
        return curr.is_leaf

    def starts_with(self, prefix: str) -> bool:
        if not isinstance(prefix, str):
            raise TypeError('prefix must be a string')
        if not prefix:
            return True
        curr = self.root
        i = 0
        while i < len(prefix):
            char = prefix[i]
            if char not in curr.children:
                return False
            child = curr.children[char]
            edge = child.prefix
            remaining = len(prefix) - i
            if remaining < len(edge):
                return edge.startswith(prefix[i:])
            if not prefix.startswith(edge, i):
                return False
            i += len(edge)
            curr = child
        return True

class _IntervalNode:
    def __init__(self, center: float, left_node=None, right_node=None, by_start=None, by_end=None):
        self.center = center
        self.left = left_node
        self.right = right_node
        self.by_start = by_start or []
        self.by_end = by_end or []

class IntervalTree:
    def __init__(self, intervals: list):
        if not isinstance(intervals, list):
            raise TypeError('intervals must be a list')
        clean_intervals = []
        for item in intervals:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError('Invalid interval')
            s, e = item
            if not isinstance(s, (int, float)) or not isinstance(e, (int, float)) or isinstance(s, bool) or isinstance(e, bool):
                raise TypeError('Interval bounds must be numbers')
            if s > e:
                raise ValueError('Invalid interval: start > end')
            clean_intervals.append((s, e))

        self.root = self._build_tree(clean_intervals)

    def _build_tree(self, intervals):
        if not intervals:
            return None
        center = sum(s + e for s, e in intervals) / (2.0 * len(intervals))
        left_set, right_set, center_set = [], [], []
        for s, e in intervals:
            if e < center:
                left_set.append((s, e))
            elif s > center:
                right_set.append((s, e))
            else:
                center_set.append((s, e))

        node = _IntervalNode(center)
        node.by_start = sorted(center_set, key=lambda x: x[0])
        node.by_end = sorted(center_set, key=lambda x: x[1], reverse=True)
        node.left = self._build_tree(left_set)
        node.right = self._build_tree(right_set)
        return node

    def query_point(self, point: int | float) -> list:
        if not isinstance(point, (int, float)) or isinstance(point, bool):
            raise TypeError('point must be numeric')
        res = []

        def _query(node):
            if not node:
                return
            if point < node.center:
                for s, e in node.by_start:
                    if s <= point:
                        res.append((s, e))
                    else:
                        break
                _query(node.left)
            else:
                for s, e in node.by_end:
                    if e >= point:
                        res.append((s, e))
                    else:
                        break
                _query(node.right)

        _query(self.root)
        return sorted(res, key=lambda x: x[0])

import re

def match_semver_range(version: str, constraint: str) -> bool:
    if not isinstance(version, str) or not isinstance(constraint, str):
        raise TypeError('Inputs must be strings')

    semver_pattern = re.compile(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$')
    m = semver_pattern.match(version.strip())
    if not m:
        raise ValueError('Invalid SemVer format')
    v_tuple = tuple(int(x) for x in m.groups())

    constraint = constraint.strip()
    if constraint in ('*', ''):
        return True

    clauses = constraint.split()
    for clause in clauses:
        if clause.startswith('^'):
            base_v = clause[1:]
            bm = semver_pattern.match(base_v)
            if not bm:
                raise ValueError(f'Invalid SemVer in caret constraint: {clause}')
            b_tuple = tuple(int(x) for x in bm.groups())
            # ^1.2.3 -> >=1.2.3 <2.0.0; ^0.2.3 -> >=0.2.3 <0.3.0
            if b_tuple[0] > 0:
                upper = (b_tuple[0] + 1, 0, 0)
            elif b_tuple[1] > 0:
                upper = (0, b_tuple[1] + 1, 0)
            else:
                upper = (0, 0, b_tuple[2] + 1)
            if not (b_tuple <= v_tuple < upper):
                return False
            continue

        op = ''
        for candidate in ('>=', '<=', '==', '>', '<'):
            if clause.startswith(candidate):
                op = candidate
                break
        if not op:
            raise ValueError(f'Invalid constraint operator in: {clause}')

        target_v = clause[len(op):]
        tm = semver_pattern.match(target_v)
        if not tm:
            raise ValueError(f'Invalid SemVer target in clause: {clause}')
        t_tuple = tuple(int(x) for x in tm.groups())

        if op == '>=' and not (v_tuple >= t_tuple): return False
        if op == '<=' and not (v_tuple <= t_tuple): return False
        if op == '==' and not (v_tuple == t_tuple): return False
        if op == '>' and not (v_tuple > t_tuple): return False
        if op == '<' and not (v_tuple < t_tuple): return False

    return True

import re

def extract_nested_path(data: dict | list, path: str, default=None):
    if not isinstance(data, (dict, list)):
        raise TypeError('data must be a dict or list')
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if not path:
        return data

    # Validación sintáctica de corchetes no balanceados o índices no numéricos
    if '[' in path or ']' in path:
        # Debe contener solo pares de [digitos]
        cleaned = re.sub(r'\[\d+\]', '', path)
        if '[' in cleaned or ']' in cleaned:
            raise ValueError('Malformed array index in path')

    # Tokenizar claves y corchetes: ej. 'users[0].address' -> ['users', 0, 'address']
    segments = path.split('.')
    tokens = []
    for seg in segments:
        if not seg:
            continue
        matches = re.findall(r'([^\[]+)|\[(\d+)\]', seg)
        for key_part, idx_part in matches:
            if key_part:
                tokens.append(key_part)
            elif idx_part:
                tokens.append(int(idx_part))

    curr = data
    for token in tokens:
        if isinstance(token, str):
            if isinstance(curr, dict) and token in curr:
                curr = curr[token]
            else:
                return default
        elif isinstance(token, int):
            if isinstance(curr, list) and 0 <= token < len(curr):
                curr = curr[token]
            else:
                return default
        else:
            return default
    return curr

