def get_next_cron_run(cron_expr: str, current_time: datetime) -> datetime:
    if not isinstance(cron_expr, str) or not isinstance(current_time, datetime):
        raise TypeError('cron_expr must be str and current_time must be datetime')

    fields = cron_expr.strip().split()
    if len(fields) != 5:
        raise ValueError('cron_expr must have 5 fields')

    field_ranges = [
        (0, 59),  # minute
        (0, 23),  # hour
        (1, 31),  # day_of_month
        (1, 12),  # month
        (0, 6)    # day_of_week (0=Mon, 6=Sun)
    ]

    def _parse_field(field_str, min_val, max_val):
        allowed = set()
        parts = field_str.split(',')
        for p in parts:
            if not p:
                raise ValueError('Invalid cron field syntax')
            step = 1
            if '/' in p:
                base, step_str = p.split('/', 1)
                if not step_str.isdigit() or int(step_str) <= 0:
                    raise ValueError('Invalid cron field syntax')
                step = int(step_str)
            else:
                base = p
            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                s_str, e_str = base.split('-', 1)
                if not s_str.isdigit() or not e_str.isdigit():
                    raise ValueError('Invalid cron field syntax')
                start, end = int(s_str), int(e_str)
            elif base.isdigit():
                start, end = int(base), int(base)
            else:
                raise ValueError('Invalid cron field syntax')

            if start < min_val or end > max_val or start > end:
                raise ValueError('Invalid cron field syntax')
            for v in range(start, end + 1, step):
                allowed.add(v)
        return allowed

    allowed_mins = _parse_field(fields[0], 0, 59)
    allowed_hours = _parse_field(fields[1], 0, 23)
    allowed_doms = _parse_field(fields[2], 1, 31)
    allowed_months = _parse_field(fields[3], 1, 12)
    allowed_dows = _parse_field(fields[4], 0, 6)

    # Avanzar al siguiente minuto completo
    candidate = current_time.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Buscar hasta un máximo de 5 años (2,628,000 minutos)
    max_minutes = 60 * 24 * 366 * 5
    for _ in range(max_minutes):
        if candidate.month in allowed_months and candidate.day in allowed_doms and candidate.weekday() in allowed_dows and candidate.hour in allowed_hours and candidate.minute in allowed_mins:
            return candidate
        candidate += timedelta(minutes=1)

    raise ValueError('No matching cron time found within 5 years')

import asyncio

class AsyncDebouncer:
    def __init__(self, wait_seconds: float):
        if not isinstance(wait_seconds, (int, float)) or isinstance(wait_seconds, bool) or wait_seconds <= 0:
            raise ValueError('wait_seconds must be a positive number')
        self.wait_seconds = float(wait_seconds)
        self._pending_task = None
        self._pending_future = None

    async def call(self, coro_fn: callable, *args, **kwargs):
        if not callable(coro_fn):
            raise TypeError('coro_fn must be callable')

        loop = asyncio.get_running_loop()
        if self._pending_task and not self._pending_task.done():
            self._pending_task.cancel()
            if self._pending_future and not self._pending_future.done():
                self._pending_future.set_result(None)

        self._pending_future = loop.create_future()
        future = self._pending_future

        async def _debounced_worker():
            try:
                await asyncio.sleep(self.wait_seconds)
                res = await coro_fn(*args, **kwargs)
                if not future.done():
                    future.set_result(res)
            except asyncio.CancelledError:
                if not future.done():
                    future.set_result(None)
            except Exception as e:
                if not future.done():
                    future.set_exception(e)

        self._pending_task = asyncio.create_task(_debounced_worker())
        return await future

class Pipeline:
    def __init__(self):
        self._middlewares = []

    def use(self, middleware: callable) -> 'Pipeline':
        if not callable(middleware):
            raise TypeError('middleware must be callable')
        self._middlewares.append(middleware)
        return self

    def execute(self, initial_context: dict) -> dict:
        if not isinstance(initial_context, dict):
            raise TypeError('initial_context must be a dictionary')

        # Construcción recursiva de la cadena onion de atrás hacia adelante
        def _final_step(ctx):
            return ctx

        next_fn = _final_step
        for mw in reversed(self._middlewares):
            current_mw = mw
            current_next = next_fn
            next_fn = (lambda m, n: lambda ctx: m(ctx, lambda: n(ctx)))(current_mw, current_next)

        return next_fn(dict(initial_context))

class Specification:
    def is_satisfied_by(self, candidate: dict) -> bool:
        raise NotImplementedError

    def __and__(self, other):
        if not isinstance(other, Specification):
            return NotImplemented
        return _AndSpecification(self, other)

    def __or__(self, other):
        if not isinstance(other, Specification):
            return NotImplemented
        return _OrSpecification(self, other)

    def __invert__(self):
        return _NotSpecification(self)

class _AndSpecification(Specification):
    def __init__(self, spec1, spec2):
        self.spec1 = spec1
        self.spec2 = spec2
    def is_satisfied_by(self, candidate: dict) -> bool:
        if not isinstance(candidate, dict):
            raise TypeError('candidate must be a dictionary')
        return self.spec1.is_satisfied_by(candidate) and self.spec2.is_satisfied_by(candidate)

class _OrSpecification(Specification):
    def __init__(self, spec1, spec2):
        self.spec1 = spec1
        self.spec2 = spec2
    def is_satisfied_by(self, candidate: dict) -> bool:
        if not isinstance(candidate, dict):
            raise TypeError('candidate must be a dictionary')
        return self.spec1.is_satisfied_by(candidate) or self.spec2.is_satisfied_by(candidate)

class _NotSpecification(Specification):
    def __init__(self, spec):
        self.spec = spec
    def is_satisfied_by(self, candidate: dict) -> bool:
        if not isinstance(candidate, dict):
            raise TypeError('candidate must be a dictionary')
        return not self.spec.is_satisfied_by(candidate)

class AttrEqualsSpecification(Specification):
    def __init__(self, key: str, value):
        if not isinstance(key, str):
            raise TypeError('key must be a string')
        self.key = key
        self.value = value
    def is_satisfied_by(self, candidate: dict) -> bool:
        if not isinstance(candidate, dict):
            raise TypeError('candidate must be a dictionary')
        return candidate.get(self.key) == self.value

class AttrGreaterThanSpecification(Specification):
    def __init__(self, key: str, threshold: float | int):
        if not isinstance(key, str):
            raise TypeError('key must be a string')
        if not isinstance(threshold, (int, float)) or isinstance(threshold, bool):
            raise TypeError('threshold must be numeric')
        self.key = key
        self.threshold = threshold
    def is_satisfied_by(self, candidate: dict) -> bool:
        if not isinstance(candidate, dict):
            raise TypeError('candidate must be a dictionary')
        val = candidate.get(self.key)
        if val is None or not isinstance(val, (int, float)) or isinstance(val, bool):
            return False
        return val > self.threshold
